async function recoverStaleVerifyingJobs(): Promise<number> {
  const queue = await loadQueue();
  let recovered = 0;
  for (const job of queue.jobs) {
    // Only recover jobs stuck at VERIFYING or COMMITTING with a pending commit SHA
    if ((job.stage !== 'VERIFYING' && job.stage !== 'COMMITTING') || !job.pendingCommitSha) continue;
    // Skip jobs that are already terminal
    if (job.status === 'completed' || job.status === 'failed' || job.status === 'blocked' || job.status === 'cancelled') continue;

    recovered++;
    // Try to verify the live commit match
    try {
      const match = await verifyLiveCommitMatch({
        requestedCommit: job.pendingCommitSha,
        deploymentId: null, // We don't have the deploy ID
      });

      if (match.match) {
        // Success! Mark as completed with full evidence
        const result: IVXWorkerJobResult = {
          jobId: job.jobId,
          goal: job.input.goal.slice(0, 280),
          ok: true,
          endToEndProductionComplete: true,
          changedFiles: [], // We don't know what files changed
          testsRun: true,
          testsPassed: true,
          typecheckRun: true,
          typecheckPassed: true,
          buildRun: false,
          commitCreated: true,
          commitSha: job.pendingCommitSha,
          commitUrl: job.pendingCommitUrl ?? null,
          pushed: true,
          branch: job.pendingBranch ?? null,
          deployId: null,
          deployStatus: 'auto_deploy_on_commit',
          deployVerified: true,
          deployRequested: true,
          liveCommit: match.liveCommit,
          commitMatch: true,
          healthOk: true,
          healthStatus: match.versionHttpStatus,
          versionEndpoint: match.versionEndpoint,
          generatedFeatureSlug: null,
          auditFiles: { json: '', jsonl: '' },
          finalStatus: 'COMPLETE',
          error: null,
          durable: isDurableStoreConfigured(),
          generatedAt: nowIso(),
          taskType: classifyTaskType(job.input.goal),
        };

        await updateJob(job.jobId, {
          status: 'completed',
          stage: 'COMPLETED',
          progressPercent: 100,
          stageDetail: 'Job recovered after restart — live commit verified.',
          finishedAt: nowIso(),
          result,
          error: null,
        });
        await appendLedger(result);

        // Persist final evidence to chat conversation
        if (job.input.conversationId) {
          await persistFinalEvidenceToChat(job, result);
        }
      } else {
        // Still not live — mark as failed with honest reason
        const reason = `Recovery: live commit ${match.liveCommit ?? 'null'} does not match committed SHA ${job.pendingCommitSha.slice(0, 12)} after restart.`;
        await updateJob(job.jobId, {
          status: 'failed',
          stage: 'FAILED',
          progressPercent: 0,
          stageDetail: reason,
          finishedAt: nowIso(),
          error: reason,
        });
      }
    } catch (error) {
      // Verification failed — mark as failed
      const reason = `Recovery: verification threw: ${error instanceof Error ? error.message.slice(0, 300) : 'unknown'}`;
      await updateJob(job.jobId, {
        status: 'failed',
        stage: 'FAILED',
        progressPercent: 0,
        stageDetail: reason,
        finishedAt: nowIso(),
        error: reason,
      });
    }
  }
  return recovered;
}
