async function persistFinalEvidenceToChat(job: IVXWorkerJob, result: IVXWorkerJobResult): Promise<void> {
  if (!job.input.conversationId) return;
  const supabaseUrl = (process.env.SUPABASE_URL ?? process.env.IVX_SUPABASE_URL ?? process.env.EXPO_PUBLIC_SUPABASE_URL ?? '').replace(/\/$/, '');
  const serviceRoleKey = (process.env.SUPABASE_SERVICE_ROLE_KEY ?? '').trim();
  if (!supabaseUrl || !serviceRoleKey) return;

  const answer = buildTerminalEvidenceAnswer(job, result);

  try {
    await fetch(`${supabaseUrl}/rest/v1/messages`, {
      method: 'POST',
      headers: {
        apikey: serviceRoleKey,
        Authorization: `Bearer ${serviceRoleKey}`,
        'Content-Type': 'application/json',
        Prefer: 'return=representation',
      },
      body: JSON.stringify({
        conversation_id: job.input.conversationId,
        sender_id: ASSISTANT_SENDER_ID,
        text: answer,
      }),
    });
  } catch {
    // Non-fatal — the ledger still has the proof
  }
}
```

