```typescript
/**
 * Boot-time and pre-drain recovery: find jobs stuck at VERIFYING or COMMITTING
 * with a pendingCommitSha (persisted before the Render deploy killed the worker).
 * Verifies the live commit match and marks a terminal state with full evidence.
 * Also persists the final evidence to the IVX IA Chat conversation.
 */
export async function recoverStaleVerifyingJobs(): Promise<number> {
  const queue = await loadQueue();
  let recovered = 0;
  for (const job of queue.jobs) {
    if (job.status === 'completed' || job.status === 'failed' || job.status === 'blocked' || job.status === 'cancelled') continue;
    if ((job.stage !== 'VERIFYING' && job.stage !== 'COMMITTING') || !job.pendingCommitSha) continue;
    // Only recover jobs older than 30 seconds (give the deploy time to land)
    if (job.startedAt && Date.now() - new Date(job.startedAt).getTime() < 30_000) continue;

    recovered += 1;
    console.log('[IVX-SeniorDevWorker] Recovering stale verifying job', { jobId: job.jobId, pendingCommitSha: job.pendingCommitSha.slice(0, 12), stage: job.stage });

    try {
      const match = await verifyLiveCommitMatch({
        requestedCommit: job.pendingCommitSha,
        deploymentId: null,
        maxVersionAttempts: 8,
        versionPollIntervalMs: 3_000,
      });

      if (match.match) {
        const result: IVXWorkerJobResult = {
          jobId: job.jobId,
          goal: job.input.goal.slice(0, 280),
          ok: true,
          endToEndProductionComplete: true,
          changedFiles: [],
          testsRun: true,
          testsPassed: true,
          typecheckRun: true,
          typecheckPassed: true,
          buildRun: false,
          commitCreated: true,
          commitSha: job.pendingCommitSha,
          commitUrl: job.pendingCommitUrl ?? null,
          pushed: true,
          branch: job.pendingBranch ?? null,
          deployId: null,
          deployStatus: 'auto_deploy_on_commit',
          deployVerified: true,
          deployRequested: true,
          liveCommit: match.liveCommit,
          commitMatch: true,
          healthOk: true,
          healthStatus: match.versionHttpStatus,
          versionEndpoint: match.versionEndpoint,
          generatedFeatureSlug: null,
          auditFiles: { json: '', jsonl: '' },
          finalStatus: 'COMPLETE',
          error: null,
          durable: isDurableStoreConfigured(),
          generatedAt: nowIso(),
          taskType: classifyTaskType(job.input.goal),
        };

        await updateJob(job.jobId, {
          status: 'completed',
          stage: 'COMPLETED',
          progressPercent: STAGE_PROGRESS['COMPLETED'],
          stageDetail: 'Job recovered after restart — live commit verified.',
          finishedAt: nowIso(),
          result,
          error: null,
        });
        await appendLedger(result);

        // Persist final evidence to IVX IA Chat conversation
        if (job.input.conversationId) {
          await persistFinalEvidenceToChat(job, result).catch(() => null);
        }

        console.log('[IVX-SeniorDevWorker] Stale verifying job recovered to COMPLETED', { jobId: job.jobId, commitSha: job.pendingCommitSha.slice(0, 12) });
      } else {
        // Still not live after retries — mark as failed with honest reason
        const reason = `Recovery: live commit ${match.liveCommit ?? 'null'} does not match committed SHA ${job.pendingCommitSha.slice(0, 12)} after ${match.versionAttempts} attempts.`;
        const failedResult: IVXWorkerJobResult = {
          jobId: job.jobId,
          goal: job.input.goal.slice(0, 280),
          ok: false,
          endToEndProductionComplete: false,
          changedFiles: [],
          testsRun: true,
          testsPassed: true,
          typecheckRun: true,
          typecheckPassed: true,
          buildRun: false,
          commitCreated: true,
          commitSha: job.pendingCommitSha,
          commitUrl: job.pendingCommitUrl ?? null,
          pushed: true,
          branch: job.pendingBranch ?? null,
          deployId: null,
          deployStatus: null,
          deployVerified: false,
          deployRequested: true,
          liveCommit: match.liveCommit,
          commitMatch: false,
          healthOk: false,
          healthStatus: match.versionHttpStatus,
          versionEndpoint: match.versionEndpoint,
          generatedFeatureSlug: null,
          auditFiles: { json: '', jsonl: '' },
          finalStatus: 'FAILED',
          error: reason,
          durable: isDurableStoreConfigured(),
          generatedAt: nowIso(),
          taskType: classifyTaskType(job.input.goal),
        };

        await updateJob(job.jobId, {
          status: 'failed',
          stage: 'FAILED',
          progressPercent: STAGE_PROGRESS['FAILED'],
          stageDetail: reason,
          finishedAt: nowIso(),
          result: failedResult,
          error: reason,
        });
        await appendLedger(failedResult);

        if (job.input.conversationId) {
          await persistFinalEvidenceToChat(job, failedResult).catch(() => null);
        }

        console.log('[IVX-SeniorDevWorker] Stale verifying job recovery FAILED — commit not live', { jobId: job.jobId, reason });
      }
    } catch (error) {
      const reason = `Recovery: verification threw: ${error instanceof Error ? error.message.slice(0, 300) : 'unknown'}`;
      await updateJob(job.jobId, {
        status: 'failed',
        stage: 'FAILED',
        progressPercent: STAGE_PROGRESS['FAILED'],
        stageDetail: reason,
        finishedAt: nowIso(),
        error: reason,
      });
      console.log('[IVX-SeniorDevWorker] Stale verifying job recovery threw', { jobId: job.jobId, reason });
    }
  }
  return recovered;
}
```

For the `persistFinalEvidenceToChat` function:

```typescript
const ASSISTANT_SENDER_ID = (process.env.IVX_ASSISTANT_SENDER_ID ?? '9b280e15-f9fd-459f-bf2d-530b1ed84cb1').trim();

/**
 * Persist the final terminal evidence as an assistant message in the IVX IA
 * Chat conversation. Called after recovery completes a stuck job so the owner
 * sees the verified result in chat without polling the status URL.
 */
async function persistFinalEvidenceToChat(job: IVXWorkerJob, result: IVXWorkerJobResult): Promise<void> {
  if (!job.input.conversationId) return;
  const supabaseUrl = (process.env.SUPABASE_URL ?? process.env.IVX_SUPABASE_URL ?? process.env.EXPO_PUBLIC_SUPABASE_URL ?? '').replace(/\/$/, '');
  const serviceRoleKey = (process.env.SUPABASE_SERVICE_ROLE_KEY ?? '').trim();
  if (!supabaseUrl || !serviceRoleKey) return;

  const answer = [
    `TASK ID: ${job.jobId}`,
    `STATUS: ${result.ok ? 'COMPLETED' : 'FAILED'}`,
    `FINAL STATUS: ${result.finalStatus}`,
    `COMMIT SHA: ${result.commitSha ?? 'NONE'}`,
    `COMMIT URL: ${result.commitUrl ?? 'NONE'}`,
    `LIVE COMMIT: ${result.liveCommit ?? 'NONE'}`,
    `COMMIT MATCH: ${result.commitMatch ? 'true' : 'false'}`,
    `HEALTH: ${result.healthOk ? 'OK' : 'UNKNOWN'}`,
    `HEALTH HTTP: ${result.healthStatus ?? 'N/A'}`,
    `DEPLOYMENT: ${result.deployId ? `deployId=${result.deployId} status=${result.deployStatus}` : 'auto_deploy_on_commit'}`,
    `PRODUCTION VERIFICATION: ${result.deployVerified ? 'VERIFIED' : 'NOT VERIFIED'}`,
    `TESTS: ${result.testsPassed ? 'PASS' : 'FAIL'}`,
    `TYPECHECK: ${result.typecheckRun ? (result.typecheckPassed ? 'PASS' : 'FAIL') : 'NOT RUN'}`,
    `APPROVALS: ${(job.input.approvals ?? []).map(a => `${a.action}(${a.id.slice(0, 12)}, expires=${a.expiresAt})`).join('; ') || 'NONE'}`,
    `EVIDENCE SOURCE: post_restart_recovery`,
    result.error ? `ERROR: ${result.error}` : 'ERROR: NONE',
  ].join('\n');

  try {
    const res = await fetch(`${supabaseUrl}/rest/v1/messages`, {
      method: 'POST',
      headers: {
        apikey: serviceRoleKey,
        Authorization: `Bearer ${serviceRoleKey}`,
        'Content-Type': 'application/json',
        Prefer: 'return=representation',
      },
      body: JSON.stringify({
        conversation_id: job.input.conversationId,
        sender_id: ASSISTANT_SENDER_ID,
        text: answer,
      }),
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) {
      const detail = await res.text().catch(() => '');
      console.log('[IVX-SeniorDevWorker] persistFinalEvidenceToChat failed', { httpStatus: res.status, detail: detail.slice(0, 200) });
    }
  } catch (error) {
    console.log('[IVX-SeniorDevWorker] persistFinalEvidenceToChat error:', error instanceof Error ? error.message : 'unknown');
  }
}
```

